1:/* Operations Control Panel (knowledge-base/features/ops-control-panel.md §5). Design tokens come from tokens.css. */
2:.ops-app { min-height: 100vh; display: flex; flex-direction: column; }
11:.ops-view, .ops-timeline-rule, .ops-lang {
14:.ops-view > button, .ops-timeline-rule > button, .ops-lang > button {
17:.ops-view > button:last-child, .ops-timeline-rule > button:last-child, .ops-lang > button:last-child { border-right: 0; }
18:.ops-view > button:hover:not(:disabled), .ops-timeline-rule > button:hover:not(:disabled), .ops-lang > button:hover:not(:disabled) {
21:.ops-view > button[aria-pressed="true"], .ops-timeline-rule > button[aria-pressed="true"], .ops-lang > button[aria-pressed="true"] {
31:.ops-operations { padding: 12px 16px; display: flex; flex-direction: row; gap: 12px; }
36:.ops-timeline { display: flex; flex-direction: row; gap: 4px; padding: 10px 14px 18px; border: 1px solid var(--border-primary); border-radius: 8px; background: var(--surface-card); color: var(--text-secondary); }
37:.ops-timeline-head { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin-bottom: 6px; }
38:.ops-timeline-summary { font: 600 14px var(--font-mono); color: var(--text-primary); margin-right: auto; }
39:.ops-timeline-chips, .ops-timeline-anchor { display: inline-flex; gap: 6px; align-items: center; }
40:.ops-timeline-chips > button, .ops-timeline-anchor > button { min-height: 32px; }
41:.ops-timeline-density { display: block; width: 100%; height: 28px; }
42:.ops-timeline-bar { fill: var(--border-secondary); }
43:.ops-timeline-bar.on { fill: var(--accent-primary); }
44:.ops-timeline-track { position: relative; height: 24px; cursor: pointer; touch-action: none; user-select: none; }
45:.ops-timeline-rail { position: absolute; left: 0; right: 0; top: 10px; height: 4px; border-radius: 2px; background: var(--bg-tertiary); }
46:.ops-timeline-band { position: absolute; top: 8px; height: 8px; border-radius: 4px; background: color-mix(in srgb, var(--accent-primary) 55%, transparent); cursor: grab; }
47:.ops-timeline-band:active { cursor: grabbing; }
48:.ops-timeline-now { position: absolute; top: 0; width: 2px; height: 24px; margin-left: -1px; background: var(--accent-warning); pointer-events: none; }
49:.ops-timeline-handle { position: absolute; top: 2px; width: 14px; height: 20px; margin-left: -7px; border: 2px solid var(--surface-card); border-radius: 4px; background: var(--text-primary); cursor: ew-resize; }
50:.ops-timeline-handle:focus-visible { outline: 2px solid var(--accent-primary); outline-offset: 2px; }
51:.ops-timeline-ticks { position: relative; height: 14px; }
52:.ops-timeline-tick { position: absolute; transform: translateX(-50%); font: 10px var(--font-mono); color: var(--text-tertiary); }
53:.ops-timeline-tick:nth-child(odd) { visibility: hidden; }
54:@media (min-width: 1200px) { .ops-timeline-tick:nth-child(odd) { visibility: visible; } }
73:.ops-grid { display: flex; flex-direction: column; gap: 12px; }
74:.ops-grid--both { display: grid; grid-template-columns: minmax(0, 3fr) minmax(0, 2fr); gap: 12px; align-items: start; }
75:@media (max-width: 1200px) { .ops-grid--both { grid-template-columns: minmax(0, 1fr); } }
142:.ops-detail { display: flex; flex-direction: column; gap: 18px; color: var(--text-primary); }
160:.ops-legs { display: grid; grid-template-columns: 1fr auto 1fr; align-items: stretch; gap: 12px; }
162:.ops-leg-card { display: flex; flex-direction: column; gap: 2px; padding: 14px 16px; border: 1px solid var(--border-primary); border-radius: 10px; background: var(--surface-card); }
168:.ops-leg-times { display: grid; grid-template-columns: max-content 1fr; gap: 4px 14px; margin: 0; font-size: 13px; }
171:.ops-progress { display: flex; flex-direction: column; gap: 6px; }
174:.ops-detail-section { display: flex; flex-direction: column; gap: 10px; padding-top: 14px; border-top: 1px solid var(--border-primary); }
191:.ops-crew-list { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 300px), 1fr)); gap: 6px; margin: 0; padding: 0; list-style: none; }
198:.ops-crew-list--recheck { grid-template-columns: 1fr; }
236:.ops-rc-who { display: flex; flex-direction: column; min-width: 0; }
273:@media (max-width: 640px) { .ops-legs { grid-template-columns: 1fr; } .ops-legs-arrow { display: none; } }
